    <p v-if="bench.error.value" role="alert" tw-class="text-xs whitespace-pre-wrap break-words text-red-600 dark:text-red-400">{{ bench.error.value }}</p>
    <section tw-class="space-y-3">
      <h2 tw-class="font-semibold">{{ lazyStrings.imageBenchmark__results() }}</h2>
      <div tw-class="overflow-x-auto rounded-xl border border-gray-200 dark:border-gray-800">
        <table tw-class="w-full text-sm text-left"><thead tw-class="bg-gray-50 dark:bg-gray-800"><tr><th tw-class="p-3">{{ lazyStrings.imageBenchmark__run() }}</th><th tw-class="p-3">{{ lazyStrings.imageBenchmark__protocol() }}</th><th tw-class="p-3">{{ lazyStrings.imageBenchmark__results() }}</th><th tw-class="p-3">{{ lazyStrings.imageBenchmark__elapsed() }}</th><th tw-class="p-3">{{ lazyStrings.imageBenchmark__sampling() }}</th><th tw-class="p-3">{{ lazyStrings.imageBenchmark__model_load() }}</th></tr></thead>
          <tbody><tr v-for="run in bench.runs.value" :key="run.record.id" data-testid="benchmark-run" tw-class="border-t border-gray-100 dark:border-gray-800"><td tw-class="p-3"><span tw-class="block text-xs">{{ bench.plan.value?.models[run.record.modelIndex]?.target.label }}</span>{{ run.record.id }}<ImageBenchmarkResult :run-id="run.record.id" :png="run.png" :image-status="run.record.image.status" /></td><td tw-class="p-3 text-xs">{{ run.record.plannedKind === 'cold' ? lazyStrings.imageBenchmark__cold() : lazyStrings.imageBenchmark__warm() }}</td><td tw-class="p-3">{{ status({ record: run.record }) }}<p v-if="run.record.error" tw-class="text-xs text-red-600 dark:text-red-400 break-words">{{ run.record.error }}</p><p v-if="run.record.uniformOutput" tw-class="text-xs text-amber-700 dark:text-amber-300">{{ lazyStrings.stableDiffusionCppBrowser__uniform_image_warning() }}</p><p v-if="run.record.metrics.reuse && run.record.metrics.reuse.reusedWorker !== (run.record.plannedKind === 'warm')" tw-class="text-xs text-amber-700 dark:text-amber-300">{{ lazyStrings.imageBenchmark__freshness_warning() }}</p></td><td tw-class="p-3 whitespace-nowrap">{{ time({ value: run.record.elapsedMs }) }}</td><td tw-class="p-3 whitespace-nowrap">{{ time({ value: run.record.metrics.runWall?.sampling }) }}</td><td tw-class="p-3 whitespace-nowrap">{{ time({ value: run.record.metrics.runWall?.['model-load'] }) }}</td></tr></tbody>
        </table>
      </div>
      <div tw-class="flex flex-wrap gap-3 items-center"><button type="button" :disabled="bench.busy.value || bench.exporting.value || !bench.runs.value.length" @click="bench.download()" data-testid="benchmark-download" tw-class="inline-flex min-h-10 items-center rounded-xl border border-blue-200 dark:border-blue-900/50 bg-white dark:bg-gray-800 px-4 py-2 text-sm font-medium text-blue-600 dark:text-blue-400 shadow-sm transition-colors hover:bg-blue-50 dark:hover:bg-blue-900/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 disabled:opacity-40 disabled:cursor-not-allowed">{{ bench.exporting.value ? lazyStrings.imageBenchmark__exporting() : lazyStrings.imageBenchmark__download_zip() }}</button><button type="button" :disabled="bench.busy.value || bench.exporting.value || !bench.runs.value.length" @click="bench.clear()" data-testid="benchmark-clear" tw-class="inline-flex min-h-10 items-center rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 px-3 py-2 text-sm font-medium text-gray-600 dark:text-gray-300 shadow-sm transition-colors hover:bg-gray-50 dark:hover:bg-gray-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 disabled:opacity-40 disabled:cursor-not-allowed">{{ lazyStrings.imageBenchmark__new_measurement() }}</button></div>
      <label tw-class="flex items-center gap-2 text-sm"><input v-model="includePrompts" :disabled="bench.exporting.value" type="checkbox" tw-class="h-4 w-4 shrink-0 accent-blue-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 disabled:opacity-40" data-testid="benchmark-include-prompts" />{{ lazyStrings.imageBenchmark__include_prompts() }}</label>
      <label tw-class="flex items-center gap-2 text-sm"><input v-model="includeInputImages" :disabled="bench.exporting.value" type="checkbox" tw-class="h-4 w-4 shrink-0 accent-blue-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 disabled:opacity-40" true-value="include" false-value="omit" data-testid="benchmark-input-images" />{{ lazyStrings.imageBenchmark__include_input_images_in_zip() }}</label>
      <p tw-class="text-xs text-gray-500 dark:text-gray-400">{{ lazyStrings.imageBenchmark__export_privacy() }}</p>
      <p role="status" tw-class="text-xs text-blue-600 dark:text-blue-400">{{ bench.feedback.value }}</p>
    </section>
  </section>
</template>
